UPDATE public.questions SET explanation = 'Technical Rationale: XPath uses a compact NON-XML expression syntax (such as path expressions ''/catalog/book[@id=101]/title'') so that expressions can be easily embedded inside XML attributes (like in XSLT ''select'' attributes) or URIs without syntax collisions.
